package com.bank.roster;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class DeptRosterDemo {
    private static final Logger log = Logger.getLogger("DeptRoster");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(1L, "Rajesh", "IT"),
            new Employee(2L, "Priya", "Finance"),
            new Employee(3L, "Amit", "IT"),
            new Employee(4L, "Sneha", "Finance")
        );
        RosterService service = new RosterService();
        Map<String, List<String>> names = service.namesByDepartment(staff);
        names.forEach((dept, list) -> log.info(() -> dept + " -> " + list));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final String department;
    Employee(Long id, String name, String department) { this.id = id; this.name = name; this.department = department; }
    String getName() { return name; }
    String getDepartment() { return department; }
}

// ─── Would be in service/RosterService.java ───
class RosterService {
    // mapping(getName, toList()) converts each grouped Employee to its name inside the group.
    Map<String, List<String>> namesByDepartment(List<Employee> employees) {
        return employees.stream()
            .collect(groupingBy(Employee::getDepartment, TreeMap::new,
                                mapping(Employee::getName, toList())));
    }
}
